    counts = {}
    for x in a:
        # Calculate f(x)
        val = bin(x).count('1')
        if val in counts:
            counts[val] += 1
        else:
            counts[val] = 1

    # Calculate number of pairs (i, j) with i < j such that f(a_i) == f(a_j)
    # If a value appears k times, the number of pairs is k * (k - 1) / 2
    total_pairs = 0
    for count in counts.values():
        total_pairs += count * (count - 1) // 2

    print(total_pairs)

